import { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { createPortal } from 'react-dom'
import { BookMarked, BookOpen, FlaskConical, Search as SearchIcon, ShieldCheck, Table2 } from 'lucide-react'

/** One search entry, generated by scripts/gen-manifest.mjs: [kind, path, title, context label, searchable text]. */
type Entry = [kind: 'lesson' | 'exercise' | 'rule' | 'reference' | 'row', path: string, title: string, context: string, text: string]
interface Indexed { e: Entry; title: string; text: string }

/** Lower-case, and drop hyphens so "btree" finds "B-Tree" and "copy on write" finds "copy-on-write". */
const norm = (t: string) => t.toLowerCase().replace(/-/g, '')

let cache: Promise<Indexed[]> | null = null
/** The index is a separate chunk, downloaded the first time search is opened. */
const loadIndex = () => (cache ??= import('./index.json').then((m) => (m.default as unknown as Entry[]).map((e) => ({ e, title: norm(e[2]), text: `${e[3]} ${e[4]}`.toLowerCase() }))))

/** Tie-breaker in favour of teaching content: a lesson whose title matches outranks a reference row that merely starts with the word. */
const KIND_BONUS = { lesson: 25, rule: 12, exercise: 10, reference: 5, row: 0 } as const
const ICON = { lesson: BookOpen, exercise: FlaskConical, rule: ShieldCheck, reference: BookMarked, row: Table2 } as const
const LIMIT = 30

/** Every word of the query must appear; matches in the title rank above matches in the summary text. */
export function searchEntries(items: Indexed[], query: string): Entry[] {
  const words = norm(query).split(/\s+/).filter(Boolean)
  if (!words.length) return []
  const scored: { e: Entry; score: number }[] = []
  for (const it of items) {
    let score = 0
    let ok = true
    for (const w of words) {
      const at = it.title.indexOf(w)
      if (at === 0 && it.title.length === w.length) score += 12 // the whole title
      else if (at === 0) score += 8
      else if (at > 0) score += /[\s_.(-]/.test(it.title[at - 1]) ? 6 : 4
      else if (it.text.includes(w)) score += 1
      else { ok = false; break }
    }
    if (ok) scored.push({ e: it.e, score: score * 10 + (score >= 4 ? KIND_BONUS[it.e[0]] : 0) })
  }
  return scored.sort((a, b) => b.score - a.score || a.e[2].length - b.e[2].length).slice(0, LIMIT).map((s) => s.e)
}

export function SearchDialog({ onClose }: { onClose: () => void }) {
  const [q, setQ] = useState('')
  const [items, setItems] = useState<Indexed[] | null>(null)
  const [failed, setFailed] = useState(false)
  const [sel, setSel] = useState(0)
  const nav = useNavigate()
  const list = useRef<HTMLUListElement>(null)
  const results = useMemo(() => (items ? searchEntries(items, q) : []), [items, q])

  useEffect(() => { loadIndex().then(setItems, () => { cache = null; setFailed(true) }) }, [])
  useEffect(() => { setSel(0) }, [q])
  useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])
  useEffect(() => { list.current?.querySelector('[aria-selected="true"]')?.scrollIntoView({ block: 'nearest' }) }, [sel])

  const go = (e: Entry) => { onClose(); nav(e[1]) }
  const onKey = (ev: React.KeyboardEvent) => {
    if (ev.key === 'Escape') { ev.preventDefault(); onClose() }
    else if (ev.key === 'ArrowDown') { ev.preventDefault(); setSel((s) => Math.min(s + 1, results.length - 1)) }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); setSel((s) => Math.max(s - 1, 0)) }
    else if (ev.key === 'Enter' && results[sel]) { ev.preventDefault(); go(results[sel]) }
  }

  return createPortal(
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/50 p-3 pt-[8vh] sm:p-6 sm:pt-[12vh]" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose() }}>
      <div role="dialog" aria-modal="true" aria-label="Search the site" className="flex max-h-[80vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-line bg-surface shadow-2xl" onKeyDown={onKey}>
        <label className="flex items-center gap-3 border-b border-line px-4 py-3">
          <SearchIcon className="size-5 shrink-0 text-muted" aria-hidden />
          <input autoFocus value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search lessons, exercises, the production guide and the reference" data-testid="search-input"
            className="min-w-0 flex-1 bg-transparent text-base outline-none placeholder:text-muted" role="combobox" aria-expanded={results.length > 0} aria-controls="search-results" aria-autocomplete="list"
            aria-activedescendant={results[sel] ? `search-r-${sel}` : undefined} />
          <kbd className="hidden rounded border border-line px-1.5 py-0.5 text-[11px] text-muted sm:inline">Esc</kbd>
        </label>
        <ul ref={list} id="search-results" role="listbox" aria-label="Results" className="min-h-0 flex-1 overflow-y-auto scrollbar-thin">
          {results.map((e, i) => {
            const Icon = ICON[e[0]]
            return (
              <li key={e[1]} id={`search-r-${i}`} role="option" aria-selected={i === sel} onMouseMove={() => setSel(i)} onClick={() => go(e)}
                className={`flex cursor-pointer items-start gap-3 px-4 py-2.5 ${i === sel ? 'bg-accent-soft' : ''}`}>
                <Icon className="mt-0.5 size-4 shrink-0 text-accent" aria-hidden />
                <span className="min-w-0 flex-1">
                  <span className={`block truncate text-sm font-semibold ${e[0] === 'row' ? 'font-mono' : ''}`}>{e[2]}</span>
                  <span className="block truncate text-xs text-muted">{e[3]}{e[0] === 'row' && e[4] ? ` · ${e[4]}` : ''}</span>
                </span>
              </li>
            )
          })}
        </ul>
        <p className="border-t border-line px-4 py-2 text-xs text-muted" aria-live="polite">
          {failed ? 'The search index could not be loaded. Check your connection and try again.'
            : !items ? 'Loading the search index…'
            : !q.trim() ? 'Type to search every lesson, Cookbook exercise, production rule, configuration parameter, catalog, error code and glossary term.'
            : results.length === 0 ? `Nothing matches “${q.trim()}”.`
            : `${results.length === LIMIT ? `Top ${LIMIT}` : results.length} result${results.length === 1 ? '' : 's'} · ↑↓ to move, Enter to open`}
        </p>
      </div>
    </div>,
    document.body,
  )
}
